{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Verizon is one of the world’s leading providers of communications, technology, information and streaming products and services to consumers, businesses and government entities.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0085",
          "quote": "one of the world’s leading providers of communications, technology, information and streaming products and services to consumers, businesses and government entities"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Verizon operates two reportable segments, Verizon Consumer Group and Verizon Business Group.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000052-0097",
          "quote": "We have two reportable segments that we operate and manage as strategic business units - Verizon Consumer Group (Consumer) and Verizon Business Group (Business)."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Verizon operates in a highly competitive telecommunications industry, but management believes its attractive offerings, high-quality networks and customer base support its competitive position.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0128",
          "quote": "The telecommunications industry is highly competitive, and we expect competition to remain intense as traditional and non-traditional participants seek increased market share."
        },
        {
          "chunk_id": "VZ-000073271226000007-0128",
          "quote": "We believe that our attractive offerings and value proposition as well as our high-quality networks and customer base support our competitive position"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Wholesale revenues are partly generated by a few large telecommunications companies, most of which compete directly with the company.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0013",
          "quote": "A portion of Wholesale revenues are generated by a few large telecommunications companies, most of which compete directly with us."
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Revenue was {{m:revenue:FY0}} in {{p:FY0}} and {{m:revenue:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA was {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt / EBITDA was {{m:debt_to_ebitda:FY-2}} in {{p:FY-2}} and {{m:debt_to_ebitda:LTM}} in {{p:LTM}}, reflecting a stable leverage trend over the period.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Net leverage was {{m:net_leverage:FY-2}} in {{p:FY-2}} and {{m:net_leverage:LTM}} in {{p:LTM}}, also stable over the period.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA / interest weakened from {{m:interest_coverage:FY-2}} in {{p:FY-2}} to {{m:interest_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "FCF / debt was {{m:fcf_to_debt:FY-2}} in {{p:FY-2}} and {{m:fcf_to_debt:LTM}} in {{p:LTM}}, holding broadly stable.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The increase in interest expense in {{p:FY0}} compared to {{p:FY-1}} was driven by lower capitalized interest as additional C-Band spectrum licenses were placed into service, partially offset by lower average debt balances and a lower interest rate.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0096",
          "quote": "a decrease in capitalized interest due to additional C-Band spectrum licenses being placed into service"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Liquidity coverage was {{m:liquidity_coverage:FY0}} in {{p:FY0}} and declined to {{m:liquidity_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "In {{p:LTM}}, liquidity sources included {{m:cash:LTM}} of cash, {{m:short_term_investments:LTM}} of short-term investments, {{m:undrawn_revolver:LTM}} of undrawn revolving credit capacity, and {{m:cfo:LTM}} of cash from operations, against {{m:short_term_debt:LTM}} of short-term debt, {{m:capex:LTM}} of capital expenditure, and {{m:dividends:LTM}} of dividends.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Management states that its sources of funds, primarily from operations and external financing arrangements, are sufficient to meet ongoing operating and investing requirements over the next 12 months and beyond.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000023-0116",
          "quote": "Our sources of funds, primarily from operations and, to the extent necessary, from external financing arrangements"
        },
        {
          "chunk_id": "VZ-000073271226000023-0116",
          "quote": "are sufficient to meet ongoing operating and investing requirements over the next 12 months and beyond"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Cash generated from operations continues to be the company's primary source of funds.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0140",
          "quote": "Our primary source of funds continues to be cash generated from operations."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The revolving credit facility had {{m:undrawn_revolver:LTM}} of undrawn capacity, did not require compliance with financial covenants or maintenance of specified credit ratings, permitted borrowing even after a material adverse change, and had no drawings since inception.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000052-0048",
          "quote": "does not require us to comply with financial covenants or maintain specified credit ratings, and it permits us to borrow even if our business has incurred a material adverse change."
        },
        {
          "chunk_id": "VZ-000073271226000052-0048",
          "quote": "there have been no drawings against the revolving credit facility since its inception."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt maturing in the next twelve months is {{m:maturity_year_1:FY0}}, followed by {{m:maturity_year_2:FY0}} in year two and {{m:maturity_year_3:FY0}} in year three.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Debt maturing in year four is {{m:maturity_year_4:FY0}}, in year five is {{m:maturity_year_5:FY0}}, and after year five is {{m:maturity_after_year_5:FY0}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "The share of total debt due within 24 months is {{m:share_due_24m:FY0}}, and near-term maturity cover is {{m:near_term_maturity_cover:FY0}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The company's credit agreements contain covenants typical for large, investment grade companies, and Verizon and its consolidated subsidiaries were in compliance with all restrictive covenants in its debt agreements.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0149",
          "quote": "Our credit agreements contain covenants that are typical for large, investment grade companies. We and our consolidated subsidiaries are in compliance with all of our restrictive covenants in our debt agreements."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Asset-backed debt issued is included in Debt maturing within one year and Long-term debt on the consolidated balance sheets.",
      "citations": [
        {
          "chunk_id": "VZ-000073271226000007-0271",
          "quote": "The asset-backed debt issued is included in Debt maturing within one year and Long-term debt in our consolidated balance sheets."
        }
      ]
    }
  ]
}

